// Summa quotations: Dominican translation (1920, public domain), checked by script against the New Advent text. Scripture: Douay-Rheims.
addTerms([
 {id:"nestorianism",t:"Nestorianism",la:"",d:"Christology",b:"The error that divides Christ into two subjects, a divine Son and a human son, joined only morally.",p:"Nestorius (d. c.451) refused to call Mary Theotokos; the union of God and man was by indwelling, will, honour (ST III q.2 a.6). Condemned at Ephesus (431).",ex:"'Mary is mother of the man Jesus, not of God.'",where:"III q.2 a.6",ccc:"466",conf:"Distinguishing the natures, which is orthodox; Nestorianism separates the persons.",rel:["hypostatic-union","theotokos"],lesson:"t11l2",alias:["Nestorianism","Nestorius","Nestorian"]},
 {id:"monophysitism",t:"Monophysitism / Eutychianism",la:"",d:"Christology",b:"The error that Christ has only one nature after the union, the human absorbed into the divine.",p:"Eutyches (d. c.456) confessed Christ 'from two natures' but not 'in two natures' (III q.2 a.6). Condemned at Chalcedon (451). Some 'miaphysite' Churches today are judged to share the orthodox faith in substance (Common Christological Declarations, e.g. 1984, 1994).",ex:"'The humanity of Christ dissolved in his divinity like a drop of honey in the sea.'",where:"III q.2 a.6",ccc:"467",conf:"Miaphysite Christology of the Oriental Orthodox, now recognised as largely terminological.",rel:["hypostatic-union","miaphysite"],lesson:"t11l2",alias:["monophysitism","Eutychianism","Eutyches","monophysite"]},
 {id:"apollinarianism",t:"Apollinarianism",la:"",d:"Christology",b:"The error that the Word took the place of Christ's human mind or soul.",p:"Apollinaris of Laodicea (d. 390) held that Christ had a human body and lower soul but no human intellect (III q.5 aa.3–4). Condemned at Constantinople I (381). Answered by Gregory of Nazianzus: \"what has not been assumed has not been healed\".",ex:"",where:"III q.5",ccc:"471",conf:"",rel:["hypostatic-union"],lesson:"t11l2",alias:["Apollinarianism","Apollinaris"]},
 {id:"monothelitism",t:"Monothelitism",la:"",d:"Christology",b:"The error that Christ has only one will.",p:"A 7th-century compromise (Sergius, Cyrus) holding two natures but one will and one operation. Maximus the Confessor and Pope Martin I opposed it; Constantinople III (681) defined two natural wills and operations, the human freely subject to the divine (DS 556; III q.18).",ex:"",where:"III q.18",ccc:"475",conf:"",rel:["hypostatic-union"],lesson:"t11l2",alias:["monothelitism","monothelite","two wills"]},
 {id:"fittingness",t:"Fittingness (argument from)",la:"convenientia",d:"Christology",b:"Showing why something God freely did was most suitable, without claiming he had to do it.",p:"An argument ex convenientia shows that a free divine act fits God's goodness and our good, so that it is 'necessary' only in the sense that a horse is necessary for a journey: the end is better reached by it (III q.1 a.2).",ex:"Why the Son, not the Father, became incarnate (III q.3 a.8).",where:"III q.1 a.2; q.3 a.8",ccc:"",conf:"Demonstration; fittingness does not prove necessity.",rel:["psych-analogy"],lesson:"t11l3",alias:["fittingness","convenientia","fitting"]},
 {id:"grace-union",t:"Grace of union / capital grace",la:"gratia unionis / gratia capitis",d:"Christology",b:"The grace of the humanity being united to the Word (union); and Christ's fullness of grace overflowing to his members (capital).",p:"The grace of union is the personal being given gratuitously to the human nature in the Word (III q.2 a.10). Christ also had habitual grace in fullness (q.7), and as Head of the Church his grace overflows to all members (q.8): \"of his fulness we all have received\" (John 1:16).",ex:"",where:"III qq.2, 7–8",ccc:"",conf:"Adoption; Christ is Son by nature, not adoptive son (q.23 a.4).",rel:["hypostatic-union","grace","mystical-body"],lesson:"t11l5",alias:["grace of union","capital grace","habitual grace of Christ","head of the Church"]},
 {id:"christ-knowledge",t:"Christ's threefold human knowledge",la:"scientia beata, infusa, acquisita",d:"Christology",b:"Thomas's teaching that Christ's human soul had the vision of God, infused knowledge, and knowledge acquired by experience.",p:"Beatific knowledge (seeing the Word, III q.10), infused knowledge (as angels have, q.11), acquired knowledge (by the agent intellect from experience, in which he truly grew, q.12; Luke 2:52). The beatific vision in the earthly Christ is classical teaching (Mystici Corporis 75) though discussed by modern theologians.",ex:"\"Jesus advanced in wisdom and age and grace\" (Luke 2:52).",where:"III qq.9–12",ccc:"472–474",conf:"The divine knowledge of the Word, which is not 'in' the human soul.",rel:["beatific-vision","intellect"],lesson:"t11l5",alias:["beatific knowledge of Christ","infused knowledge","acquired knowledge"]}
]);

mkLessons("t11",[
// ===================== L2 COUNCILS =====================
{id:"t11l2",ord:2,code:"T11 · Lesson 2",title:"Christ confessed: Scripture and the councils from Nicaea to Constantinople III",
 outcomes:["Trace the New Testament witness to Jesus as truly God and truly man.","Identify the major Christological errors (Docetism, Arianism, Apollinarianism, Nestorianism, Eutychianism, Monothelitism) and their refutations.","Explain what Ephesus (431) and Chalcedon (451) defined, and the four Chalcedonian adverbs.","Explain the two wills defined at Constantinople III (681) and the role of Maximus the Confessor.","Explain the principle 'what has not been assumed has not been healed' and the soteriological logic of the councils."],
 prereq:["hypostatic-union","nestorianism","monophysitism","apollinarianism","monothelitism","homoousios","theotokos"],
 recall:[
  ["t4l2","What did Nicaea (325) define about the Son, and why the word homoousios?","That the Son is 'consubstantial' with the Father, God from God, begotten not made; the non-scriptural word was needed because Arians re-read every biblical phrase."],
  ["t4l4","What did the Cappadocians mean by hypostasis, and what does Thomas say 'person' signifies?","Hypostasis: the concrete subsistent; person: an individual substance of a rational nature; in God, a subsisting relation."],
  ["t11","What is the hypostatic union?","The union of divine and human natures in the one person (hypostasis) of the Word."],
  ["t3l2","What is the difference between nature and suppositum?","Nature is what a thing is (humanity); the suppositum is the concrete individual that has the nature (this man)."]],
 reading:{primary:[["Council of Ephesus (431): Cyril's second letter to Nestorius",'https://www.papalencyclicals.net/councils/ecum03.htm'],["Council of Chalcedon (451): Definition of faith",'https://www.papalencyclicals.net/councils/ecum04.htm'],["Leo the Great, Tome to Flavian (449)",'https://www.newadvent.org/fathers/3604028.htm'],["Council of Constantinople III (681): Definition",'https://www.papalencyclicals.net/councils/ecum06.htm'],["CCC 456–483",'https://www.vatican.va/archive/ENG0015/__P1L.HTM']],
  secondary:["Grillmeier, A. (1975) Christ in Christian Tradition, vol. 1. 2nd edn. London: Mowbray.","Kelly, J.N.D. (1977) Early Christian Doctrines, chs 11–12.","McGuckin, J.A. (2004) Saint Cyril of Alexandria and the Christological Controversy. Crestwood: SVS Press.","Louth, A. (1996) Maximus the Confessor. London: Routledge."]},
 scripture:[["John 1:14, the Word was made flesh","j1-14"],["Philippians 2:6–8, emptied himself, taking the form of a servant",null],["Colossians 2:9, the fulness of the Godhead corporeally",null],["Hebrews 4:15, tempted in all things like as we are, without sin",null]],
 sections:[
 {id:"s1",h:"1. The New Testament witness",html:`<p>The New Testament presents Jesus both as fully human and as sharing the identity of the one God.</p>
<ul><li><strong>Truly man.</strong> He is born of a woman, grows (\"Jesus advanced in wisdom and age and grace\", Luke 2:52), hungers, weeps, is \"tempted in all things like as we are, without sin\" (Heb 4:15), and dies.</li>
<li><strong>Truly God.</strong> \"The Word was God… And the Word was made flesh\" (John 1:1, 14); \"in him dwelleth all the fulness of the Godhead corporeally\" (Col 2:9); he forgives sins, receives worship, and is called 'Lord' with the divine name's honour (Phil 2:9–11).</li>
<li><strong>One subject.</strong> The same 'he' is \"in the form of God\" and \"emptied himself, taking the form of a servant… obedient unto death\" (Phil 2:6–8).</li></ul>
${RC("t4l2",`<p>T4 L2 traced the Trinitarian controversies. Christological doctrine developed in the same way and often in the same decades: once the Son was confessed <strong>homoousios</strong> with the Father, the question became how this divine Son is also one of us.</p>`)}
<p><strong>Early errors.</strong> <em>Docetism</em> (Christ only seemed to have a body; opposed by Ignatius of Antioch, c.110) and <em>adoptionism</em> (Jesus a man adopted as Son) were rejected early.</p>`,
  check:Q("Which text says the same subject was 'in the form of God' and 'took the form of a servant'?",[["John 1:14","It says the Word became flesh."],["Philippians 2:6–8","Correct."],["Hebrews 4:15","It concerns temptation."]],1)},
 {id:"s2",h:"2. A whole humanity: Apollinarius and 'what is not assumed'",html:`<p>Apollinaris of Laodicea (d. 390), a defender of Nicaea, tried to secure Christ's unity by saying the divine Word took the place of the human mind. Christ had a human body and lower soul but no human intellect.</p>
<p>Gregory of Nazianzus answered with a principle that governs all later Christology: \"For that which He has not assumed He has not healed; but that which is united to His Godhead is also saved\" (<em>Letter</em> 101, to Cledonius). If the mind, the seat of sin, was not assumed, the mind is not redeemed. Constantinople I (381) condemned Apollinarianism.</p>
${RC("f5",`<p>F5: the human soul's highest powers are <strong>intellect and will</strong>. Apollinarianism amputates exactly what makes man human. Thomas follows Gregory: the Son assumed "an entire human nature, i.e. not only a body, but also a soul, and not only a sensitive, but also a rational soul" (III q.9 a.1; q.5 aa.3–4).</p>`)}`,
  check:Q("What did Apollinaris deny Christ had?",[["A body","He admitted a body."],["A human mind (intellect)","Correct."],["A divine nature","He affirmed it."]],1)},
 {id:"s3",h:"3. One subject: Ephesus (431)",html:`<p><strong>Nestorius</strong>, Patriarch of Constantinople (428), objected to calling Mary <em>Theotokos</em>, 'God-bearer'. Mary bore the man Jesus, in whom the Word dwelt. Thomas summarises the Nestorian picture: the Word and the man were united \"by indwelling\", \"by unity of intention\", \"by operation\", \"by greatness of honor\", \"by equivocation\" (III q.2 a.6): all accidental unions.</p>
<p><strong>Cyril of Alexandria</strong> answered: the Word himself, remaining what he was, became man; so the one born of Mary is God, and Mary is Mother of God. The Council of Ephesus (431) approved Cyril's second letter to Nestorius and deposed Nestorius.</p>
${RC("t12",`<p>T12 began here: <strong>Theotokos</strong> is first a Christological title. It protects the truth that Mary's son is the divine Word, not a man who became the dwelling of God.</p>`)}
${RC("t4l4",`<p>T4 L4's rules of speech return in Christology: what is said of the <em>person</em> can be said of him in either nature. "God was born of Mary" and "God died" are true, because the subject is the divine person. This is the <strong>communication of idioms</strong> (L4).</p>`)}`,
  check:Q("What title of Mary did Nestorius reject?",[["Mother of Christ","He accepted that."],["Theotokos, Mother of God","Correct."],["Virgin","No."]],1)},
 {id:"s4",h:"4. Two natures: Chalcedon (451)",html:`<p><strong>Eutyches</strong>, an archimandrite of Constantinople, overcorrected: Christ was 'from two natures' before the union but in one nature after it, the humanity absorbed. Pope Leo I's <em>Tome</em> (449) taught: \"each form does what is proper to it in communion with the other\". The Council of Chalcedon (451) defined:</p>
<div class="quote">"…one and the same Christ, Son, Lord, only-begotten, acknowledged in two natures which undergo no confusion, no change, no division, no separation; at no point was the difference between the natures taken away through the union, but rather the property of both natures is preserved and comes together into a single person and a single subsistent being."<span class="src">Council of Chalcedon, Definition of faith (451), DS 302; tr. Tanner (1990)</span></div>
<div class="tablewrap"><table class="t"><thead><tr><th>Adverb</th><th>Excludes</th></tr></thead><tbody>
<tr><td>Without confusion (asynchytōs)</td><td>Eutyches: natures mixed</td></tr>
<tr><td>Without change (atreptōs)</td><td>Divinity turned into humanity or vice versa</td></tr>
<tr><td>Without division (adiairetōs)</td><td>Nestorius: two subjects</td></tr>
<tr><td>Without separation (achōristōs)</td><td>Natures ever apart</td></tr></tbody></table></div>
<p><strong>Aftermath.</strong> Several Eastern Churches rejected Chalcedon's language (the 'Oriental Orthodox': Coptic, Armenian, Syriac, Ethiopian). Modern dialogue has found that much of the disagreement was terminological: e.g. the Common Christological Declaration of Pope John Paul II and the Assyrian Church of the East (1994), and with the Syrian Orthodox (1984).</p>
${RC("t3l2",`<p>T3 L2: in God, <strong>nature and suppositum</strong> are identical. Chalcedon's formula is possible because the Word is a divine person who can be the subject of a second nature without ceasing to be what he is.</p>`)}`,
  check:Q("Which Chalcedonian adverb excludes Eutyches' error?",[["Without division","That excludes Nestorius."],["Without confusion","Correct."],["Without separation","That excludes the natures being apart."]],1)},
 {id:"s5",h:"5. Two wills: Constantinople II and III (553, 681)",html:`<p><strong>Constantinople II (553)</strong> interpreted Chalcedon in Cyril's sense: \"one of the Trinity was crucified in the flesh\" (DS 432).</p>
<p><strong>Monothelitism.</strong> To reconcile the Monophysites, Patriarch Sergius proposed (c.630s) that Christ had two natures but one 'operation' and then one will. Maximus the Confessor (d. 662) argued that will belongs to nature, not person: if Christ has a human nature, he has a human will, and Gethsemane shows it: \"not as I will but as thou wilt\" (Matt 26:39). Maximus and Pope Martin I were exiled and died for this.</p>
<p><span class="voice">Magisterium</span><strong>Constantinople III (681)</strong> defined two natural wills and two natural operations in Christ, not opposed to each other: the human will follows the divine, without resisting or struggling, subject to the divine and all-powerful will (DS 556).</p>
${RC("t6l2",`<p>T6 L2 analysed the <strong>human act</strong>: intention, choice, consent. Constantinople III means Christ performed truly human acts in this full sense. His obedience was a human obedience, freely chosen; that is why it could redeem (L8).</p>`)}
<div class="co check"><div class="co-h">The logic of the councils</div><p>Each council protects one truth needed for salvation: that the Saviour is truly God (Nicaea), truly and wholly man (Constantinople I against Apollinarius), one subject (Ephesus), in two unconfused natures (Chalcedon), with a true human will (Constantinople III). Remove any one, and the healing of human nature by God fails.</p></div>`,
  check:Q("Who argued that will belongs to nature, so Christ has a human will?",[["Sergius","He proposed one will."],["Maximus the Confessor","Correct."],["Nestorius","No."]],1)}
 ],
 quiz:[
  Q("'In him dwelleth all the fulness of the Godhead corporeally' is from…",[["Colossians 2:9","Correct."],["John 1:14","No."],["Hebrews 1:3","No."],["Philippians 2:6","No."]],0,"Col 2:9",{bloom:"Remember",terms:[],diff:1}),
  Q("'What has not been assumed has not been healed' was written against…",[["Arius","No."],["Apollinaris","Correct: Gregory of Nazianzus, Ep. 101."],["Nestorius","No."],["Eutyches","No."]],1,"Gregory Naz., Ep. 101",{bloom:"Remember",terms:["apollinarianism"],diff:1}),
  Q("Which council defined Theotokos?",[["Nicaea","No."],["Ephesus (431)","Correct."],["Chalcedon","No."],["Trent","No."]],1,"Ephesus 431",{bloom:"Remember",terms:["theotokos"],diff:1}),
  Q("Nestorius held that the union of God and man in Christ was…",[["substantial, in one hypostasis","That is orthodox."],["accidental: indwelling, will, honour","Correct: III q.2 a.6."],["a mixture of natures","That is Eutyches."],["imaginary","That is Docetism."]],1,"III q.2 a.6",{bloom:"Understand",terms:["nestorianism"],diff:2}),
  Q("Leo's Tome taught that…",[["Christ has one nature","No."],["each form does what is proper to it in communion with the other","Correct."],["Christ had no human mind","No."],["Mary is not Theotokos","No."]],1,"Tome of Leo",{bloom:"Remember",terms:[],diff:2}),
  Q("'Without division, without separation' excludes…",[["Eutyches","No: confusion and change exclude him."],["Nestorius","Correct."],["Arius","No."],["Apollinaris","No."]],1,"Chalcedon",{bloom:"Analyse",terms:["nestorianism"],diff:2}),
  Q("'One of the Trinity was crucified in the flesh' was affirmed by…",[["Nicaea","No."],["Constantinople II (553)","Correct: DS 432."],["Ephesus","No."],["Vatican II","No."]],1,"DS 432",{bloom:"Remember",terms:["communicatio"],diff:2}),
  Q("Monothelitism held that Christ has…",[["one nature","Monophysitism."],["two natures but one will","Correct."],["two persons","Nestorianism."],["no human soul","Apollinarianism."]],1,"",{bloom:"Remember",terms:["monothelitism"],diff:1}),
  Q("Constantinople III (681) taught that Christ's human will is…",[["absent","No."],["opposed to the divine will","No."],["subject to the divine will, not resisting","Correct: DS 556."],["the same as the divine will","No: two wills."]],2,"DS 556",{bloom:"Remember",terms:["monothelitism"],diff:2}),
  Q("The Oriental Orthodox Churches today are judged largely to share the faith in substance because…",[["they accepted Chalcedon","They did not."],["much of the disagreement was terminological, as recent common declarations recognise","Correct."],["they are Nestorian","No."],["they deny Christ's divinity","No."]],1,"Common Christological Declarations",{bloom:"Evaluate",terms:["miaphysite"],diff:3})
 ],
 construct:{q:"Whether the union of the Incarnate Word took place in the Person?",ref:"ST III q.2 a.2",
  model:{obj:"It seems not: the Person of God is not distinct from his nature; so if the union was not in the nature, it was not in the person either. Further, human nature in Christ has no less dignity than in us; in us it has its own personality; so in Christ too.",sc:"\"And the Word was made flesh\" (John 1:14); the Word is a person; so the union was made in the person.",resp:"Person differs from nature: nature is the specific essence signified by the definition; person adds whatever further belongs to the individual subsisting in that nature. In the Word, what belongs to the human nature is united to him not as nature but as person: everything in Christ, human and divine, belongs to the one person of the Word. So the union took place in the person, not in the nature.",rep:"In God person and nature are the same in reality but differ in mode of signifying. The human nature in Christ is not less dignified for lacking its own personality; it is more dignified, being in the person of the Word."},
  rubric:["Objection argues from the identity of person and nature in God, or from human dignity.","Sed contra quotes John 1:14.","Respondeo distinguishes nature and person.","Respondeo: everything in Christ belongs to the one person of the Word.","Reply: lacking a human personality is a greater dignity, not a lesser."]},
 drill:{title:"Put the Christological councils in order",parts:["Nicaea I (325): the Son homoousios","Constantinople I (381): against Apollinarius; the Spirit","Ephesus (431): Theotokos; against Nestorius","Chalcedon (451): two natures, one person","Constantinople II (553): one of the Trinity crucified","Constantinople III (681): two wills"]},
 connections:`<p><strong>Back.</strong> T4 L2 (Nicaea, the Cappadocians), T4 L4 (person, hypostasis), T3 L2 (nature and suppositum), T12 (Theotokos), F5 (intellect and will).</p><p><strong>Forward.</strong> L3–L6 give Thomas's systematic account of what the councils defined; L8 shows why a true human will matters for redemption.</p><p><strong>Apologetics.</strong> Disputations on Jehovah's Witness and Muslim objections to Christ's divinity.</p>`},

// ===================== L3 WHY THE INCARNATION =====================
{id:"t11l3",ord:3,code:"T11 · Lesson 3",title:"Cur Deus homo? Why God became man (ST III q.1; q.3 a.8)",
 outcomes:["Give Thomas's argument from the self-diffusiveness of goodness for the fittingness of the Incarnation (q.1 a.1).","Explain the two senses of 'necessary' and the ten benefits of the Incarnation (q.1 a.2).","Set out the debate on whether the Word would have become incarnate if man had not sinned (q.1 a.3; Scotus).","Explain why the Incarnation came at the 'fulness of time', neither at the beginning nor at the end (q.1 aa.5–6).","Explain why it was most fitting that the Son, rather than the Father or Spirit, became incarnate (q.3 a.8)."],
 prereq:["fittingness","incarnation","good-ratio","verbum-mentis","satisfaction"],
 recall:[
  ["t5","Why does God create, according to I q.44 a.4?","To communicate his perfection, which is his goodness."],
  ["t3l10","Could God have done otherwise than he did?","Yes: he acts by will, and his wisdom is not exhausted by the present order (I q.25 a.5)."],
  ["t4l3","Why is 'Word' the proper name of the Son, and how does the Word relate to creatures?","Because he proceeds by way of intellect; in uttering himself the Father utters all creatures in the Word, their exemplar (I q.34 aa.2–3)."],
  ["t6l8","What did the first sin take away?","Original justice, and with it the harmony of the soul; it wounded nature without destroying it."]],
 reading:{primary:[["ST III q.1 aa.1–6 (the fitness of the Incarnation)",NA("4001.htm")],["ST III q.3 a.8 (why the Son)",NA("4003.htm#article8")],["Anselm, Cur Deus Homo (1098), book I chs 11–15; book II chs 6–7",'https://sourcebooks.web.fordham.edu/basis/anselm-curdeus.asp'],["Athanasius, On the Incarnation, chs 6–10, 54",'https://www.newadvent.org/fathers/2802.htm'],["CCC 456–460",'https://www.vatican.va/archive/ENG0015/__P1L.HTM']],
  secondary:["Torrell, J.-P. (2011) Christ and Spirituality in St Thomas Aquinas. Washington, DC: CUA Press, ch. 1.","Wawrykow, J. (2005) 'Hypostatic union', in Van Nieuwenhove, R. and Wawrykow, J. (eds) The Theology of Thomas Aquinas. Notre Dame: UNDP, pp. 222–251.","Scotus, J.D. Ordinatio III d.7 q.3 (the absolute primacy of Christ).","White, T.J. (2015) The Incarnate Lord: A Thomistic Study in Christology. Washington, DC: CUA Press, ch. 1."]},
 scripture:[["John 3:16, God so loved the world",null],["Galatians 4:4, when the fulness of the time was come",null],["1 Timothy 1:15, Christ Jesus came into this world to save sinners",null],["Colossians 1:15–17, the firstborn of every creature",null]],
 sections:[
 {id:"s1",h:"1. Fitting, because goodness gives itself (q.1 a.1)",html:`<div class="quote">"But the very nature of God is goodness… But it belongs to the essence of goodness to communicate itself to others… Hence it belongs to the essence of the highest good to communicate itself in the highest manner to the creature."<span class="src">ST III q.1 a.1 · Dominican tr. (1920)</span></div>
<p>The highest way is that God join created nature to himself \"that one Person is made up of these three—the Word, a soul and flesh\" (Augustine). So the Incarnation is fitting.</p>
${RC("t3l3",`<p>T3 L3: <strong>goodness</strong> is diffusive of itself; God is goodness itself. Creation communicates God's goodness by giving being; the Incarnation communicates it in the highest possible way, by giving God's own personal existence to a created nature.</p>`)}
<p><strong>No change in God (ad 1).</strong> The Incarnation was not completed by God's changing, but by his uniting the creature to himself in a new way. The change is in the creature.</p>
${RC("t4l7",`<p>Exactly as with the <strong>missions</strong> (T4 L7): the Son 'comes' not by moving, but by a new created effect. The Incarnation is the supreme visible mission.</p>`)}`,
  check:Q("Thomas's first argument for the fittingness of the Incarnation rests on…",[["the need to punish sin","No."],["the self-communicating nature of goodness, which God is","Correct: q.1 a.1."],["Old Testament prophecy alone","No."]],1)},
 {id:"s2",h:"2. Necessary? Two senses, and ten benefits (q.1 a.2)",html:`<p>Something is necessary for an end in two ways: absolutely (food for life) or for the end's better attainment (a horse for a journey). The Incarnation was not necessary in the first way: \"God with His omnipotent power could have restored human nature in many other ways.\" It was necessary in the second: Augustine: \"there was not a more fitting way of healing our misery.\"</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Furthering us in good</th><th>Withdrawing us from evil</th></tr></thead><tbody>
<tr><td>Faith: made certain by God himself speaking</td><td>Not to prefer the devil to ourselves, since God united himself to human nature</td></tr>
<tr><td>Hope: \"Nothing was so necessary for raising our hope as to show us how deeply God loved us\"</td><td>To know our dignity and not sully it by sin: \"Learn, O Christian, thy worth\" (Leo)</td></tr>
<tr><td>Charity: \"What greater cause is there of the Lord's coming than to show God's love for us?\"</td><td>To destroy presumption: grace given without merits</td></tr>
<tr><td>Example: \"God was made man, that He Who might be seen by man… might be shown to man\"</td><td>To heal pride by God's humility</td></tr>
<tr><td>Deification: \"God was made man, that man might be made God\"</td><td>To free man from servitude by satisfaction from one who is God and man</td></tr></tbody></table></div>
${RC("t3l10",`<p>T3 L10 (I q.25 a.5): God could have done otherwise. Hence Thomas's arguments here are <strong>arguments of fittingness</strong> (convenientia): showing how wise and loving the chosen way is, not that no other way was possible.</p>`)}
<div class="co bridge"><div class="co-h">Anselm's Cur Deus Homo</div><p>Anselm (1098) argued that the restoration of man required satisfaction that only man <em>ought</em> to make and only God <em>could</em> make; so a God-man was necessary. Thomas accepts the satisfaction motif (L8) but softens 'necessity' to fittingness: God could have forgiven without satisfaction, but satisfaction better shows his justice and mercy together (III q.46 a.1 ad 3).</p></div>`,
  check:Q("In what sense, for Thomas, was the Incarnation 'necessary' for our restoration?",[["Absolutely: there was no other way","He denies this."],["As a better and more fitting way to the end, like a horse for a journey","Correct: q.1 a.2."],["Not at all","It was necessary in the second sense."]],1)},
 {id:"s3",h:"3. If Adam had not sinned? (q.1 a.3)",html:`<p>\"There are different opinions about this question.\" Thomas inclines to the view that the Incarnation would not have happened without sin:</p>
<div class="quote">"Hence, since everywhere in the Sacred Scripture the sin of the first man is assigned as the reason of Incarnation, it is more in accordance with this to say that the work of Incarnation was ordained by God as a remedy for sin; so that, had sin not existed, Incarnation would not have been. And yet the power of God is not limited to this; even had sin not existed, God could have become incarnate."<span class="src">ST III q.1 a.3 · Dominican tr. (1920)</span></div>
<p>Note the method: what depends on God's free will can be known only by revelation, and Scripture gives sin as the reason (\"Christ Jesus came into this world to save sinners\", 1 Tim 1:15).</p>
<p><strong>The Scotist view.</strong> Duns Scotus (d.1308) argued for the <em>absolute primacy of Christ</em>: God first willed Christ as the masterpiece of creation, and would have become incarnate even without sin; redemption is the mode the Incarnation took because of sin (cf. Col 1:15–17, \"the firstborn of every creature… all things were created by him and in him\"). The question remains open; Franciscans traditionally hold Scotus's view, Dominicans Thomas's.</p>
${RC("t3l9",`<p>T3 L9: in God there is one eternal decree, not a sequence of decisions. Thomists like Cajetan and later Garrigou-Lagrange argued that the debate is about the order <em>of motives</em> within one decree, which permits partial reconciliation: God willed Christ as Redeemer in a world in which he permitted sin.</p>`)}`,
  check:Q("Why does Thomas incline to think the Incarnation was ordained as a remedy for sin?",[["Because God could not otherwise become incarnate","He says God could have."],["Because Scripture everywhere assigns sin as the reason, and God's free will is known only by revelation","Correct: q.1 a.3."],["Because Scotus said so","Scotus held the opposite."]],1)},
 {id:"s4",h:"4. When: the fulness of time (q.1 aa.5–6)",html:`<p><strong>Not at the beginning (a.5).</strong> Man had to learn his need for a deliverer by experiencing his weakness, first under the natural law (ignorance) and then under the written law (weakness despite knowledge). And the dignity of the one coming required many heralds: the prophets.</p>
<p><strong>Not at the end (a.6).</strong> Then faith and knowledge of God might have died out, and the world would have lacked the Saviour's healing for too long. So: \"when the fulness of the time was come, God sent his Son, made of a woman\" (Gal 4:4).</p>
${RC("t6l11",`<p>T6 L11: the <strong>Old Law</strong> was a pedagogue leading to Christ (Gal 3:24) and could not give the grace to fulfil it. q.1 a.5 explains why that pedagogy had to come first: humanity had to learn it could not save itself.</p>`)}`,
  check:Q("Why was it not fitting for the Incarnation to occur at the very beginning, according to q.1 a.5?",[["Because man had to learn his need of a deliverer through experience of weakness","Correct."],["Because God was not ready","No."],["Because Mary was not yet born","Not Thomas's reason."]],0)},
 {id:"s5",h:"5. Why the Son? (q.3 a.8)",html:`<p>Any divine person could have become incarnate (q.3 a.5). But it was most fitting that the Son did:</p>
<ol><li><strong>From the union.</strong> The Word is the Father's eternal concept, the exemplar of all creatures, as a craftsman's concept is the exemplar of his works. As the craftsman restores his work by the same art that made it, so the Word restores the fallen creature. And the Word is Wisdom, from whom all human wisdom derives; man, rational, is perfected by participating in him.</li>
<li><strong>From the end.</strong> Predestination is to the inheritance, which belongs to sons: \"If sons, heirs also\" (Rom 8:17). So the natural Son should make us adopted sons.</li>
<li><strong>From the sin.</strong> The first sin was a disordered desire for knowledge (\"you shall be as Gods, knowing good and evil\", Gen 3:5); so it was fitting that man be led back to God by the Word of true wisdom.</li></ol>
${RC("t4l3",`<p>T4 L3 (I q.34 a.3): the Word implies relation to creatures, since the Father utters every creature in him. q.3 a.8 draws the consequence: the one through whom all things were made is the one through whom they are remade.</p>`)}`,
  check:Q("Which reason for the Son's Incarnation appeals to adoption and inheritance?",[["From the union","Exemplar and Wisdom."],["From the end: predestination to the inheritance of sons","Correct."],["From the sin","Disordered desire for knowledge."]],1)}
 ],
 quiz:[
  Q("'It belongs to the essence of goodness to communicate itself to others' is attributed to…",[["Dionysius","Correct: q.1 a.1."],["Aristotle","No."],["Anselm","No."],["Leo","No."]],0,"III q.1 a.1",{bloom:"Remember",terms:[],diff:2}),
  Q("Did the Incarnation change God?",[["Yes","No: q.1 a.1 ad 1."],["No: God united the creature to himself in a new way; the change is in the creature","Correct."],["Only the Son","No."],["Only temporarily","No."]],1,"III q.1 a.1 ad 1",{bloom:"Understand",terms:["immutability"],diff:1}),
  Q("A horse for a journey illustrates necessity…",[["absolute","Food for life is absolute."],["for the better attainment of an end","Correct: q.1 a.2."],["of coercion","No."],["of nature","No."]],1,"III q.1 a.2",{bloom:"Apply",terms:["fittingness"],diff:1}),
  Q("'Learn, O Christian, thy worth' is from…",[["Augustine","No."],["Pope Leo the Great","Correct."],["Thomas","No."],["Anselm","No."]],1,"III q.1 a.2",{bloom:"Remember",terms:[],diff:1}),
  Q("Anselm's Cur Deus Homo argued that a God-man was…",[["merely fitting","That is Thomas's softening."],["necessary for satisfaction that man ought and only God could make","Correct."],["unnecessary","No."],["impossible","No."]],1,"Anselm",{bloom:"Understand",terms:["satisfaction"],diff:2}),
  Q("Who held the 'absolute primacy of Christ' (Incarnation even without sin)?",[["Thomas","He inclined the other way."],["Duns Scotus","Correct."],["Augustine","No."],["Nestorius","No."]],1,"Scotus",{bloom:"Remember",terms:[],diff:1}),
  Q("Thomas's ground for thinking the Incarnation was a remedy for sin is…",[["philosophical necessity","No."],["that Scripture everywhere assigns sin as its reason","Correct: q.1 a.3."],["a papal decree","No."],["Aristotle","No."]],1,"III q.1 a.3",{bloom:"Understand",terms:[],diff:2}),
  Q("'When the fulness of the time was come, God sent his Son' is from…",[["Galatians 4:4","Correct."],["Romans 5","No."],["John 3","No."],["Hebrews 1","No."]],0,"Gal 4:4",{bloom:"Remember",terms:[],diff:1}),
  Q("Why was it fitting for the Son, as Word, to restore creation?",[["As a craftsman restores his work by the art that made it","Correct: q.3 a.8."],["Because the Father was busy","No."],["Because the Spirit cannot act","No."],["By chance","No."]],0,"III q.3 a.8",{bloom:"Analyse",terms:["verbum-mentis"],diff:2}),
  Q("Which sin does Thomas connect with the Word's Incarnation in q.3 a.8?",[["Murder","No."],["Disordered desire for knowledge ('you shall be as Gods')","Correct."],["Gluttony","No."],["Envy","No."]],1,"III q.3 a.8",{bloom:"Remember",terms:[],diff:2})
 ],
 construct:{q:"Whether, if man had not sinned, God would have become incarnate?",ref:"ST III q.1 a.3",
  model:{obj:"It seems so: if the cause remains, the effect remains; other reasons for the Incarnation (manifesting God's goodness, perfecting the universe) would remain without sin. Further, it belongs to God's omnipotence to perfect his works by some infinite effect.",sc:"Augustine: \"If man had not sinned, the Son of Man would not have come\"; and 1 Tim 1:15: \"Christ Jesus came into this world to save sinners\".",resp:"There are different opinions. Things that spring from God's will beyond the creature's due can be known only by revelation in Scripture. Since Scripture everywhere assigns the sin of the first man as the reason of the Incarnation, it is more in accordance with this to say it was ordained as a remedy for sin, so that without sin it would not have been. Yet God's power is not limited: he could have become incarnate even without sin.",rep:"The other reasons all relate to the remedy for sin; and God's goodness can be manifested in many ways."},
  rubric:["Objection argues from other reasons that would remain without sin.","Sed contra cites Augustine or 1 Tim 1:15.","Respondeo: free divine decisions known only by revelation.","Respondeo: Scripture assigns sin as reason; God could have done otherwise.","Reply shows the other reasons relate to the remedy."]},
 drill:{title:"Order the stages of preparation for the Incarnation (q.1 a.5)",parts:["Man left to himself under the natural law, learning ignorance","The written Law given, revealing weakness","The prophets herald the coming one","The fulness of time: God sends his Son"]},
 connections:`<p><strong>Back.</strong> T3 L3 (diffusive good), L10 (God could do otherwise), T4 L3 (the Word as exemplar), L7 (missions), T6 L8, L11 (sin and the Old Law).</p><p><strong>Forward.</strong> L4 (how the union is made), L8 (satisfaction and the Cross), T12 (Mary at the fulness of time).</p><p><strong>Liturgy.</strong> The Exsultet's 'O happy fault' and the Angelus apply this lesson.</p>`},

// ===================== L4 HYPOSTATIC UNION =====================
{id:"t11l4",ord:4,code:"T11 · Lesson 4",title:"The hypostatic union: one person, two natures, one being (qq.2–6, 16–17)",
 outcomes:["Explain why the union is not in the nature but in the person or hypostasis (q.2 aa.1–3).","Explain why the union is not accidental, and is the greatest of unions (q.2 aa.6, 9).","State what the Word assumed: a whole human nature, body, soul and mind, of Adam's stock, not a pre-existing person (qq.4–6).","Apply the rules of the communication of idioms, including what may and may not be said (q.16).","Explain Thomas's teaching on the one being (esse) of Christ and why it is debated (q.17 a.2)."],
 prereq:["hypostatic-union","communicatio","person","suppositum","esse","nestorianism"],
 recall:[
  ["t11l2","What did Chalcedon define?","One person in two natures, without confusion, change, division or separation."],
  ["t4l4","What does 'person' signify in God?","A subsisting relation; in general, an individual substance of a rational nature."],
  ["f4","What is esse, and how does it relate to essence in creatures?","The act of being; in creatures it is received and limited by essence, really distinct from it."],
  ["t3l6","What is the difference between the thing signified and the mode of signifying?","The thing signified may belong to God properly; the mode of signifying is taken from creatures."]],
 reading:{primary:[["ST III q.2 aa.1–12 (the mode of union)",NA("4002.htm")],["ST III q.4 aa.1–6 (what was assumed)",NA("4004.htm")],["ST III q.5 aa.1–4 (the parts of human nature assumed)",NA("4005.htm")],["ST III q.16 aa.1–12 (what belongs to Christ in being and becoming)",NA("4016.htm")],["ST III q.17 aa.1–2 (Christ's unity of being)",NA("4017.htm")],["CCC 464–470",'https://www.vatican.va/archive/ENG0015/__P1L.HTM']],
  secondary:["White, T.J. (2015) The Incarnate Lord, chs 2–3.","Gondreau, P. (2009) 'The humanity of Christ, the incarnate Word', in Van Nieuwenhove and Wawrykow (eds) The Theology of Thomas Aquinas, pp. 252–276.","Gorman, M. (2017) Aquinas on the Metaphysics of the Hypostatic Union. Cambridge: Cambridge University Press.","Cross, R. (2002) The Metaphysics of the Incarnation: Thomas Aquinas to Duns Scotus. Oxford: Oxford University Press."]},
 scripture:[["John 1:14, the Word was made flesh","j1-14"],["Philippians 2:7, taking the form of a servant",null],["Acts 3:15, the author of life you killed",null],["1 Corinthians 2:8, they would never have crucified the Lord of glory",null]],
 sections:[
 {id:"s1",h:"1. Not in the nature, but in the person (q.2 aa.1–3)",html:`<p><strong>Not in the nature (a.1).</strong> 'Nature' signifies the specific essence. If the union were in the nature, there would be a mixture (Eutyches) or a composite third nature. But the divine nature is infinite and cannot be mixed; and the result would be neither God nor man.</p>
<p><strong>In the person (a.2).</strong> A person (in rational beings) includes whatever belongs to the individual subsisting in a nature. \"whatever adheres to a person is united to it in person, whether it belongs to its nature or not\". And if the human nature were not united to the Word in person, \"it is nowise united to Him; and thus belief in Incarnation is altogether done away with\". So the human nature, belonging to the Word, is united to him in his person.</p>
<p><strong>In the hypostasis (a.3).</strong> Some medieval masters held one person but two hypostases in Christ. Thomas: in rational beings person and hypostasis coincide; two hypostases would be two subjects, which is Nestorianism.</p>
${RC("t11l2",`<p>L2: Chalcedon said the natures come together "into a single person and a single subsistent being (hypostasis)". q.2 aa.2–3 is the scholastic explanation of those words.</p>`)}
${RC("t3l2",`<p>T3 L2: <strong>nature</strong> is what is signified by the definition (humanity); the <strong>suppositum</strong> is the concrete individual (this man). In Christ the human nature is complete, but its suppositum is the Word.</p>`)}`,
  check:Q("Why can the union not be in the nature?",[["Because natures cannot be known","No."],["Because a union in nature would mix them, and the divine nature cannot be mixed; the result would be neither God nor man","Correct: q.2 a.1."],["Because Christ has no human nature","He does."]],1)},
 {id:"s2",h:"2. Not accidental; the greatest of unions; by grace (q.2 aa.6–12)",html:`<p><strong>Not accidental (a.6).</strong> Thomas reviews Nestorius's five modes of union (indwelling, intention, operation, honour, equivocation) and three medieval opinions, and concludes that the union is substantial as to the person: the human nature is not an accident of the Word, nor is the Word an accident of a man.</p>
<p><strong>Something created? (a.7).</strong> The union is a relation; in God it is a relation of reason, in the human nature a real relation, created in time.</p>
<p><strong>The greatest union (a.9).</strong> As to the things united, God and creature are infinitely distant; as to that in which they are united, the unity of the divine person is the greatest unity. So the union of the Incarnation is the greatest of unions.</p>
<p><strong>By grace (a.10)</strong>: the human nature receives personal being in the Word as a free gift, the 'grace of union'. <strong>No merits preceded it (a.11)</strong>: Christ was not a man who became God by a good life (adoptionism).</p>
${RC("t4l4",`<p>T4 L4: relations between God and creatures are real on the creature's side and of reason on God's side (I q.13 a.7). The Incarnation applies the same logic: the humanity is really related to the Word; the Word is not changed by it.</p>`)}`,
  check:Q("Why is the hypostatic union called 'the greatest of all unions' (q.2 a.9)?",[["Because the natures are mixed","They are not."],["Because the unity of the divine person in which they are united is the greatest unity","Correct."],["Because it happened first","No."]],1)},
 {id:"s3",h:"3. What the Word assumed (qq.4–6)",html:`<ul><li><strong>Human nature, not a person (q.4 a.2).</strong> What is assumed must be presupposed to the assumption; but a person in human nature is not presupposed to the Word's assumption, since the human nature never existed apart. So the Word assumed a human nature, not a man who already existed.</li>
<li><strong>Not humanity in general (a.4)</strong> but an individual nature, since nature exists only in individuals. <strong>Not in all men (a.5).</strong> <strong>Of Adam's stock (a.6)</strong>, so that the same nature that sinned might satisfy.</li>
<li><strong>A true body (q.5 a.1)</strong>, against the Manichees and Docetists; <strong>earthly, not heavenly (a.2)</strong>, against Valentinus.</li>
<li><strong>A soul (a.3)</strong> and <strong>a mind (a.4)</strong>, against Arius and Apollinaris.</li>
<li><strong>Order of assumption (q.6).</strong> All was assumed at once at conception. There is an order of nature: the Word assumed the flesh through the soul and the soul through the mind, by order of dignity (a.1–2). Origen's view that Christ's soul pre-existed is rejected (a.3).</li></ul>
${RC("t11l2",`<p>L2's principle, "what has not been assumed has not been healed", is the reason for this list. Every part of human nature that sin wounded is assumed so that it may be healed: body, sense, mind, will.</p>`)}`,
  check:Q("Why did the Son of God assume a human nature rather than a human person?",[["Because persons cannot be assumed","Not the reason given."],["Because what is assumed must be presupposed, and no human person existed before the assumption","Correct: q.4 a.2."],["Because the Word is not a person","He is."]],1)},
 {id:"s4",h:"4. The communication of idioms (q.16)",html:`<p>'Idioms' (idiōmata) are properties. Since there is one person with two natures, the properties of either nature can be predicated of the person, whichever nature he is named by (a.4):</p>
<div class="tablewrap"><table class="t"><thead><tr><th>True</th><th>False</th><th>Why</th></tr></thead><tbody>
<tr><td>God was born of Mary; God died</td><td>The divinity was born; the divinity died</td><td>Concrete terms ('God') stand for the person; abstract terms ('divinity') for the nature (aa.4–5)</td></tr>
<tr><td>This man is God</td><td>Humanity is divinity</td><td>Same reason</td></tr>
<tr><td>The Son of God suffered</td><td>The Son of God suffered in his divine nature</td><td>He suffered in his human nature</td></tr>
<tr><td>Christ, as man, is a creature</td><td>Christ is a creature (without qualification)</td><td>Avoided, as Arians said it of his person (a.8)</td></tr>
<tr><td>God was made man</td><td>Man was made God (as if a man became God)</td><td>Suggests adoptionism (a.7)</td></tr></tbody></table></div>
<p>Scripture already speaks this way: \"the author of life you killed\" (Acts 3:15); \"they would never have crucified the Lord of glory\" (1 Cor 2:8).</p>
${RC("t4l4",`<p>T4 L4: in the Trinity, 'God begets God' is true, but 'essence begets essence' is false. The same grammar of concrete and abstract terms (from T3 L6, <strong>mode of signifying</strong>) governs Christology.</p>`)}`,
  check:Q("Which statement is correct?",[["The divinity died on the Cross","Abstract terms stand for the nature."],["God died on the Cross","Correct: the concrete term stands for the person, who died in his human nature."],["Humanity is divinity","False."]],1)},
 {id:"s5",h:"5. One being in Christ? (q.17 a.2)",html:`<p>Two natures, one hypostasis: what belongs to nature is double (two natures, two operations, two wills), what belongs to the hypostasis is one. Being (esse) belongs to both: to the hypostasis as <em>that which</em> has being, to the nature as <em>that by which</em> it has being.</p>
<div class="quote">"Because in Christ there are two natures and one hypostasis, it follows that things belonging to the nature in Christ must be two; and that those belonging to the hypostasis in Christ must be only one."<span class="src">ST III q.17 a.2 · Dominican tr. (1920)</span></div>
<p>Thomas argues that the eternal being of the Word is the personal being of Christ; the human nature does not add a second personal being but is drawn into the Word's being, as a new relation of the person to the human nature. Accidental forms (like whiteness in Socrates) give a secondary being; but the human nature is not an accident.</p>
${RC("f4",`<p>F4: in creatures <strong>esse</strong> is really distinct from essence and is received by it. q.17 a.2 applies this to the most unique case: a created essence (the humanity) that does not have its own personal esse, but subsists in the uncreated esse of the Word.</p>`)}
<div class="co bridge"><div class="co-h">Contested</div><p>In the <em>Disputed Question on the Union of the Word</em> (De unione, a.4, c.1272) Thomas speaks of a 'secondary esse' of the human nature, which seems to differ from ST III q.17 a.2. Thomists still debate whether these are consistent (e.g. Gorman, 2017; White, 2015). The doctrine at stake, one personal subject, is dogma; the metaphysical account is a school opinion.</p></div>`,
  check:Q("According to III q.17 a.2, what in Christ is two and what is one?",[["Two persons, one nature","Reversed and heretical."],["What belongs to nature is two; what belongs to the hypostasis is one","Correct."],["Everything is one","No: two natures, wills, operations."]],1)}
 ],
 quiz:[
  Q("The union in Christ is in the…",[["nature","No: q.2 a.1."],["person or hypostasis","Correct: q.2 aa.2–3."],["will only","Nestorian."],["body only","No."]],1,"III q.2",{bloom:"Remember",terms:["hypostatic-union"],diff:1}),
  Q("'One person but two hypostases' in Christ amounts to…",[["orthodoxy","No."],["Nestorianism","Correct: q.2 a.3."],["Monophysitism","No."],["Arianism","No."]],1,"III q.2 a.3",{bloom:"Analyse",terms:["nestorianism"],diff:2}),
  Q("Is the human nature united to the Word accidentally?",[["Yes","No: q.2 a.6."],["No: substantially, as to the person","Correct."],["Only after the Resurrection","No."],["Only by grace of adoption","No."]],1,"III q.2 a.6",{bloom:"Understand",terms:["hypostatic-union"],diff:1}),
  Q("Did any merits of Christ precede the union?",[["Yes, his good life","Adoptionism."],["No: he was never a mere man who became God","Correct: q.2 a.11."],["Only his prayers","No."],["Mary's merits","Not the point here."]],1,"III q.2 a.11",{bloom:"Understand",terms:[],diff:2}),
  Q("Christ's human nature was taken from…",[["a heavenly substance","Valentinus' error."],["the stock of Adam","Correct: q.4 a.6."],["nothing","No."],["an angel","No."]],1,"III q.4 a.6",{bloom:"Remember",terms:[],diff:1}),
  Q("Origen held that Christ's soul…",[["was created at conception","That is Thomas's view."],["pre-existed before the flesh","Correct: q.6 a.3, rejected."],["did not exist","Apollinarian."],["was divine","No."]],1,"III q.6 a.3",{bloom:"Remember",terms:[],diff:2}),
  Q("'God died' is true because…",[["the divine nature died","No."],["the concrete term 'God' stands for the person, who died in his human nature","Correct: q.16 a.4."],["it is a metaphor","No."],["Christ was only man","No."]],1,"III q.16 a.4",{bloom:"Apply",terms:["communicatio"],diff:2}),
  Q("Why should one avoid saying, without qualification, 'Christ is a creature'?",[["It is true","Only as man."],["Because Arians said it of his person; one should add 'as man'","Correct: q.16 a.8."],["Because Christ is not man","He is."],["Because creatures are evil","No."]],1,"III q.16 a.8",{bloom:"Analyse",terms:["communicatio"],diff:3}),
  Q("'The author of life you killed' is from…",[["Acts 3:15","Correct."],["John 1","No."],["Romans 5","No."],["Hebrews 2","No."]],0,"Acts 3:15",{bloom:"Remember",terms:["communicatio"],diff:1}),
  Q("Thomas's teaching on the 'one esse' of Christ is…",[["dogma","The unity of person is dogma; the metaphysics is school opinion."],["a school opinion, debated in light of De unione a.4","Correct."],["heresy","No."],["absent from his works","No."]],1,"III q.17 a.2",{bloom:"Evaluate",terms:["esse"],diff:3})
 ],
 construct:{q:"Whether there is only one being in Christ?",ref:"ST III q.17 a.2",
  model:{obj:"It seems there are two: Damascene says whatever follows the nature is doubled in Christ, and being follows the nature, since it is from the form.",sc:"Everything is said to be a being inasmuch as it is one; Christ is one; so Christ has one being.",resp:"In Christ there are two natures and one hypostasis; what belongs to the nature is two, what belongs to the hypostasis is one. Being belongs to the hypostasis as that which has being and to the nature as that by which. If a form does not pertain to the personal being of the hypostasis (as whiteness in Socrates), it gives a being in some respect. But the human nature is united to the Son of God hypostatically, not accidentally; so it does not add a new personal being, but only a new relation of the pre-existing personal being to the human nature. So Christ is one being.",rep:"Being follows the nature as that by which something has being, not as that which has it; and since the human nature belongs to the one person, it does not double the personal being."},
  rubric:["Objection argues from being following nature.","Sed contra argues from unity.","Respondeo: nature-things double, hypostasis-things one.","Respondeo: being of the hypostasis vs being in some respect.","Reply: the human nature adds a new relation, not a second personal being."]},
 drill:{title:"Order Thomas's questions on the union (III qq.2–6)",parts:["The mode of union: in the person (q.2)","The person assuming: the Word (q.3)","The nature assumed: human (q.4)","Its parts: body, soul, mind (q.5)","The order of assumption (q.6)"]},
 connections:`<p><strong>Back.</strong> F4 (esse), T3 L2 (nature and suppositum), T3 L6 and T4 L4 (rules of speech), T11 L2 (councils).</p><p><strong>Forward.</strong> L5 (Christ's human grace, knowledge and passions), L6 (two wills), T12 (Theotokos follows from the communication of idioms), T13 (the Eucharist: the whole Christ, by concomitance).</p><p><strong>Apologetics.</strong> Answering 'How can God die?' and 'Did Jesus claim to be God?'.</p>`},

// ===================== L5 CHRIST'S HUMANITY =====================
{id:"t11l5",ord:5,code:"T11 · Lesson 5",title:"The humanity of Christ: grace, knowledge, power and the defects he assumed (qq.7–15)",
 outcomes:["Explain why Christ had habitual grace in fullness, and in what sense he is Head of the Church and of all men (qq.7–8).","Set out Thomas's account of Christ's threefold human knowledge and how he 'grew in wisdom' (qq.9–12), noting the modern discussion.","Explain the limits of Christ's human power (q.13).","Explain why Christ assumed bodily defects and passions, but not sin, ignorance or the fomes (qq.14–15).","Show how Christ's sorrow, fear and anger illuminate a Christian view of emotion."],
 prereq:["grace-union","christ-knowledge","beatific-vision","passions","mystical-body","hypostatic-union"],
 recall:[
  ["t3l6","Why can no created intellect see God's essence by nature, and what is needed?","Because the knower's mode is finite; the light of glory is needed (I q.12 aa.4–5)."],
  ["t6l12","What is habitual grace?","A quality in the soul's essence, a participation of the divine nature, from which the infused virtues flow (I-II q.110)."],
  ["t6l5","Are passions sinful in themselves?","No: they are neutral, good when ruled by reason, and passion ruled by reason increases the goodness of an act (I-II q.24)."],
  ["t11l4","What did the Word assume?","A complete individual human nature from Adam's stock: body, soul, and mind."]],
 reading:{primary:[["ST III q.7 aa.1–13 (the grace of Christ as individual)",NA("4007.htm")],["ST III q.8 aa.1–8 (the grace of Christ as Head)",NA("4008.htm")],["ST III q.9 aa.1–4 (Christ's knowledge in general)",NA("4009.htm")],["ST III q.14 aa.1–4; q.15 aa.1–10 (defects assumed)",NA("4015.htm")],["International Theological Commission (1985) The Consciousness of Christ Concerning Himself and His Mission",'https://www.vatican.va/roman_curia/congregations/cfaith/cti_documents/rc_cti_1985_coscienza-gesu_en.html'],["CCC 470–478",'https://www.vatican.va/archive/ENG0015/__P1M.HTM']],
  secondary:["Gondreau, P. (2002) The Passions of Christ's Soul in the Theology of St. Thomas Aquinas. Münster: Aschendorff.","White, T.J. (2015) The Incarnate Lord, ch. 5 ('The beatific vision of Christ').","Rahner, K. (1966) 'Dogmatic reflections on the knowledge and self-consciousness of Christ', Theological Investigations, 5, pp. 193–215.","Weinandy, T.G. (2004) 'Jesus' filial vision of the Father', Pro Ecclesia, 13(2), pp. 189–201."]},
 scripture:[["John 1:16, of his fulness we all have received",null],["Luke 2:52, Jesus advanced in wisdom and age and grace",null],["Mark 13:32, of that day or hour… nor the Son",null],["Hebrews 2:17, in all things to be made like unto his brethren",null],["Matthew 26:38, My soul is sorrowful even unto death",null]],
 sections:[
 {id:"s1",h:"1. Full of grace, and Head of the Church (qq.7–8)",html:`<p><strong>Habitual grace (q.7 a.1).</strong> Christ's soul, besides the grace of union, had habitual grace, for three reasons: its nearness to the Word, the source of grace; its dignity, its acts reaching God by knowledge and love; and his role as \"Mediator of God and men\" (1 Tim 2:5), whose grace must overflow: \"of his fulness we all have received\" (John 1:16).</p>
${RC("t6l12",`<p>T6 L12: <strong>habitual grace</strong> is a created participation of the divine nature. Christ's humanity, though united to the Word, still needs this created grace as the principle of its human acts of knowing and loving God. Union and grace are distinct.</p>`)}
<p>He had every virtue and gift, except those implying imperfection: not faith (he saw) nor hope (he possessed), as to their principal objects (q.7 aa.3–4). His grace was full and could not increase (a.12).</p>
<p><strong>Head (q.8).</strong> As the head is first in order, highest in perfection, and governs the body, so Christ is Head of the Church (a.1). Of whom? Of all men, but in different degrees: actually of those united by glory, charity or faith; potentially of all others, who may be united to him until death; and he is also Head of the angels (aa.3–4).</p>`,
  check:Q("Why did Christ lack the virtue of faith, as to its principal object?",[["Because he lacked grace","No."],["Because he saw God, and faith is of what is not seen","Correct: q.7 a.3."],["Because faith is not a virtue","It is."]],1)},
 {id:"s2",h:"2. Christ's knowledge (qq.9–12)",html:`<p>Christ had the divine knowledge as God. As man he had created knowledge, since the human soul is perfected by knowing; otherwise his soul \"would have been more imperfect than the souls of the rest of men\" (q.9 a.1). Thomas distinguishes three kinds:</p>
<div class="tablewrap"><table class="t"><thead><tr><th>Knowledge</th><th>Source</th><th>Reason</th></tr></thead><tbody>
<tr><td><strong>Beatific</strong> (q.10)</td><td>Vision of the Word, by the light of glory</td><td>Men are brought to the vision by Christ's humanity; the one who brings must himself have it (q.9 a.2)</td></tr>
<tr><td><strong>Infused</strong> (q.11)</td><td>Species infused by God, as in angels</td><td>To perfect the possible intellect in all it can know</td></tr>
<tr><td><strong>Acquired</strong> (q.12)</td><td>Experience and the agent intellect</td><td>\"Nothing that God planted in our nature was wanting\" (q.9 a.4): the agent intellect must act</td></tr></tbody></table></div>
<p>So \"Jesus advanced in wisdom\" (Luke 2:52) truly, in acquired knowledge. Thomas changed his mind here: in the <em>Sentences</em> he denied acquired knowledge proper; in the Summa he affirms it (q.12 a.2).</p>
${RC("t3l6",`<p>T3 L6: no creature sees God by nature; the <strong>light of glory</strong> is required. Christ's human soul, in Thomas's view, had it from conception, so that his humanity could lead others to the vision it already enjoyed.</p>`)}
<div class="co bridge"><div class="co-h">The modern discussion</div><p>Since the 20th century some theologians (Rahner, 1966; Galot) proposed that Christ's human consciousness had an immediate awareness of his divine sonship rather than the full beatific vision, to protect his real faith-like trust, growth and suffering. <span class="voice">Magisterium</span>Pius XII (<em>Mystici Corporis</em> 75, 1943) taught that Christ from the first moment enjoyed the beatific vision; the ITC (1985) affirmed Christ's consciousness of his identity and mission without settling the technical question; CCC 473–474 says that the human knowledge of God's Son \"expressed the divine life of his person\". Mark 13:32 ('nor the Son') is read by Thomas as not knowing <em>to reveal</em> (q.10 a.2 ad 1).</p></div>`,
  check:Q("In which kind of knowledge did Christ truly grow, according to the Summa?",[["Beatific","It could not increase."],["Infused","Given all at once."],["Acquired","Correct: q.12 a.2."]],2)},
 {id:"s3",h:"3. The defects Christ assumed (q.14)",html:`<p>Christ took a body subject to hunger, thirst, fatigue, pain and death, for three reasons:</p>
<ol><li><strong>To satisfy for us</strong>: \"one satisfies for another's sin by taking on himself the punishment due to the sin of the other\"; \"Surely he hath borne our infirmities\" (Isa 53:4).</li>
<li><strong>To cause belief in the Incarnation</strong>: without these defects he would not have seemed truly human.</li>
<li><strong>To give an example</strong> of patience in bearing them.</li></ol>
<p>He assumed these defects not as contracted from sin (he had no original sin) but freely; and only those that belong to human nature in general, not particular diseases from personal causes (q.14 a.4).</p>
${RC("t6l8",`<p>T6 L8: death and bodily defects are <strong>punishments of original sin</strong>. Christ, free of sin, took them on voluntarily. That is the root of satisfaction: he bears what is ours, though not owed by him.</p>`)}
<p>\"It behoved him in all things to be made like unto his brethren, that he might become a merciful and faithful high priest\" (Heb 2:17).</p>`,
  check:Q("Which is NOT one of the three reasons Christ assumed bodily defects (q.14 a.1)?",[["To satisfy for our sins","It is."],["To prove his true humanity","It is."],["To give an example of patience","It is."],["Because he inherited original sin","Correct: he did not."]],3)},
 {id:"s4",h:"4. Not sin, not ignorance; real passions (q.15)",html:`<p><strong>No sin (a.1).</strong> Sin does not help satisfaction (it impedes it), does not prove human nature (sin is not of nature), and is not an example of virtue. Nor the <em>fomes</em> (the inclination to sin, a.2), nor ignorance (a.3).</p>
<p><strong>True passions (aa.4–9).</strong> Christ's soul was passible: it suffered bodily pain through the body, and had true passions of the sense appetite: sorrow (\"My soul is sorrowful even unto death\", Matt 26:38), fear, wonder, anger. But in him the passions differed from ours in three ways (a.4): they never tended to anything unlawful; they never forestalled reason's judgment; and they never withdrew from reason, but stayed under it. Jerome called them 'propassions'.</p>
<p><strong>Anger (a.9)</strong>: zeal for justice, without sin, as in the cleansing of the Temple (\"the zeal of thy house hath eaten me up\").</p>
${RC("t6l5",`<p>T6 L5: passion ruled by reason <strong>increases</strong> the goodness of an act. Christ is the proof: his sorrow in Gethsemane and his tears at Lazarus's tomb are not weaknesses but the perfect human response to evil and death, wholly ordered.</p>`)}
<div class="co bridge"><div class="co-h">Psychology</div><p>Christ's passions offer a theological model of healthy emotion: full experience (he wept, was troubled, felt dread) without loss of direction. For clients who feel that grief, fear or anger are unchristian, the Gospels' portrait of Jesus, read with q.15, can be freeing. Emotional acceptance is associated with better mental health than suppression (e.g. Ford et al., 2018, <em>Journal of Personality and Social Psychology</em>, 115(6), pp. 1075–1092).</p></div>`,
  check:Q("How did Christ's passions differ from ours (q.15 a.4)?",[["They were not real","They were real."],["They never tended to the unlawful, never forestalled reason, and stayed under reason","Correct."],["They were only in his divine nature","No."]],1)},
 {id:"s5",h:"5. Power, and what Christ's humanity means for us (q.13)",html:`<p><strong>Power (q.13).</strong> Christ's soul was not omnipotent (a.1): omnipotence belongs to the divine nature. But as the instrument of the Word, his soul had power to do whatever was ordered to the end of the Incarnation, including miracles (a.2), and over his own body (a.3).</p>
${RC("t5l7",`<p>T5 L7: God works through creatures as <strong>instruments</strong>. Christ's humanity is the supreme instrument: "the instrument of the Godhead" (Damascene). Its acts are human acts, and through them divine power works our salvation (III q.48 a.6).</p>`)}
<div class="co apply"><div class="co-h">Apply · the Sacred Heart</div><p>The Church's devotion to the Sacred Heart (Pius XII, <em>Haurietis Aquas</em>, 1956) honours exactly what this lesson teaches: a true human heart, with human love and sorrow, belonging to the divine person. Pope Francis's <em>Dilexit Nos</em> (2024) renewed it: the human love of Christ is the love of God made visible.</p></div>
<div class="co check"><div class="co-h">Self-test</div><p>Can you explain: (1) why Christ needed habitual grace though united to the Word; (2) his three kinds of knowledge; (3) why he took hunger and death but not sin; (4) how his anger differed from sinful anger?</p></div>`,
  check:Q("Was Christ's human soul omnipotent?",[["Yes","No: q.13 a.1."],["No, but as instrument of the Word it had power for all that pertained to the Incarnation's end","Correct."],["It had no power","It worked miracles instrumentally."]],1)}
 ],
 quiz:[
  Q("Which is NOT one of the reasons for Christ's habitual grace (q.7 a.1)?",[["Nearness of his soul to the Word","It is."],["Dignity of his soul's acts","It is."],["His relation to the human race as Mediator","It is."],["To earn the hypostatic union","Correct: nothing earned the union."]],3,"III q.7 a.1",{bloom:"Understand",terms:["grace-union"],diff:2}),
  Q("Christ is Head of all men…",[["actually and equally","No."],["actually of those united to him, potentially of others while they live","Correct: q.8 a.3."],["only of Catholics","No."],["only of the dead","No."]],1,"III q.8 a.3",{bloom:"Understand",terms:["mystical-body"],diff:2}),
  Q("Christ's beatific knowledge was required because…",[["he needed to learn","No."],["the one who leads men to the vision must himself have it","Correct: q.9 a.2."],["angels have it","No."],["he lacked divine knowledge","No."]],1,"III q.9 a.2",{bloom:"Understand",terms:["christ-knowledge"],diff:2}),
  Q("Thomas changed his view on which knowledge of Christ between the Sentences and the Summa?",[["Beatific","No."],["Acquired","Correct: affirmed in the Summa."],["Divine","No."],["Infused","No."]],1,"III q.12 a.2",{bloom:"Remember",terms:["christ-knowledge"],diff:3}),
  Q("Pius XII taught that Christ enjoyed the beatific vision from the first moment in…",[["Humani Generis","No."],["Mystici Corporis (1943)","Correct: § 75."],["Haurietis Aquas","No."],["Munificentissimus Deus","No."]],1,"MC 75",{bloom:"Remember",terms:["christ-knowledge"],diff:2}),
  Q("Christ assumed bodily defects…",[["because he contracted original sin","No."],["freely, to satisfy, to show his true humanity, and as example","Correct: q.14."],["by accident","No."],["only after the Resurrection","No."]],1,"III q.14 a.1",{bloom:"Remember",terms:[],diff:1}),
  Q("Did Christ assume particular diseases?",[["Yes, all diseases","No: q.14 a.4."],["No: only defects common to human nature, not those from personal causes","Correct."],["Only leprosy","No."],["Only blindness","No."]],1,"III q.14 a.4",{bloom:"Understand",terms:[],diff:2}),
  Q("Christ's passions were called by Jerome…",[["vices","No."],["propassions","Correct."],["illusions","No."],["virtues","No."]],1,"III q.15 a.4",{bloom:"Remember",terms:["passions"],diff:2}),
  Q("Was there anger in Christ?",[["No","q.15 a.9 says yes, as zeal."],["Yes, as zeal for justice, without sin","Correct."],["Yes, sinful anger","No."],["Only in his divine nature","No."]],1,"III q.15 a.9",{bloom:"Remember",terms:[],diff:1}),
  Q("Christ's humanity is called 'the instrument of the Godhead' by…",[["Arius","No."],["John Damascene, followed by Thomas","Correct."],["Nestorius","No."],["Luther","No."]],1,"III q.48 a.6",{bloom:"Remember",terms:[],diff:2})
 ],
 construct:{q:"Whether Christ had any knowledge besides the Divine?",ref:"ST III q.9 a.1",
  model:{obj:"It seems not: knowledge is required to know things; Christ knew all things by the divine knowledge; so any other knowledge would be superfluous.",sc:"Christ took a soul like ours; our soul has knowledge; so Christ had created knowledge.",resp:"The Son of God assumed an entire human nature, including a rational soul. So he had created knowledge: first, for the soul's perfection, since the soul is in potency to knowing, and it was fitting that the nature by which all men are restored be perfect; second, because every nature is for its operation, and the soul's proper operation is to understand; third, because Christ's soul would otherwise be more imperfect than ours.",rep:"Divine knowledge is not the act of the human soul; the soul must have its own knowledge as its perfection. Two knowledges are not superfluous when they belong to two natures."},
  rubric:["Objection argues that divine knowledge makes created knowledge superfluous.","Sed contra argues from the likeness of Christ's soul to ours.","Respondeo: entire human nature assumed, rational soul included.","Respondeo gives reasons: perfection, operation, not less than ours.","Reply: two natures, two knowledges."]},
 drill:{title:"Order Christ's three human knowledges as Thomas treats them",parts:["Beatific knowledge (q.10)","Infused knowledge (q.11)","Acquired knowledge (q.12)"]},
 connections:`<p><strong>Back.</strong> T3 L6 (light of glory), T6 L5 (passions), L8 (penalties of sin), L12 (habitual grace), T5 L7 (instrumental causality), T11 L4.</p><p><strong>Forward.</strong> L6 (two wills; Gethsemane), L8 (satisfaction through assumed defects), T14 (Christ the Head of the Mystical Body), T13 (Christ's humanity as instrument in the sacraments).</p><p><strong>Psychology.</strong> Christ's ordered passions as a model of healthy emotion; P8.</p>`}
]);

Object.assign(EXTRAS,{
 t11l2:{plain:{version:"The early Church had to say precisely who Jesus is. Councils defended, one by one, that he is truly God, wholly man (with a human mind and will), one single person, in two natures that are neither mixed nor separated.",question:"What did the great councils teach about who Jesus is?",one:"One person, the divine Word, in two complete natures, without confusion, change, division or separation, with two wills."},
  hook:"\"God (Nicaea), whole man (Constantinople I), one (Ephesus), two natures (Chalcedon), two wills (Constantinople III)\".",
  analogy:{title:"Guardrails on a mountain road",text:"Each heresy is a cliff on one side of the road: too much unity (Eutyches), too much division (Nestorius), too little humanity (Apollinarius), too little divinity (Arius). The councils built guardrails; the road between them is the faith."},
  sort:{title:"Which error?",cats:["Nestorianism","Eutychianism","Apollinarianism","Monothelitism"],items:[["Mary is mother of the man, not of God",0],["After the union only one nature remains",1],["The Word replaced Christ's human mind",2],["Christ has only one will",3],["The Word dwelt in the man as in a temple",0],["The humanity dissolved in the divinity",1]]}},
 t11l3:{plain:{version:"God did not have to become man, but it was the most fitting way to save us: it shows his love, strengthens faith and hope, gives us an example, and makes us sharers of his nature. Thomas thinks Scripture presents the Incarnation as a remedy for sin; Scotus thought Christ would have come anyway. It was most fitting that the Son, the Word, became man.",question:"Why did God become man?",one:"Because goodness gives itself in the highest way; not absolutely necessary, but the most fitting remedy for sin; and fittingly the Word, through whom all was made."},
  hook:"\"Not food but a horse\": necessary for the better attainment of the end.",
  analogy:{title:"The artist restoring his painting",text:"When a painting is damaged, the best restorer is the artist who painted it, using the same vision that made it. The Word, the Father's 'art' in whom all was made, became man to restore what he had made."},
  sort:{title:"Which benefit of the Incarnation (q.1 a.2)?",cats:["Furthering in good","Withdrawing from evil"],items:[["Faith made certain by God speaking",0],["Hope raised by God's love shown",0],["Learning our dignity, so as not to sully it",1],["An example to follow",0],["Pride healed by God's humility",1],["Sharing the divine nature",0]]}},
 t11l4:{plain:{version:"In Jesus there is one 'who' (the divine Son) and two 'whats' (divine and human nature). Everything human in him, body, soul, mind, belongs to the Son. So we can say truly 'God was born' and 'God died', meaning the Son, in his human nature.",question:"How can one person be both God and man?",one:"The union is in the person of the Word, not in the natures; so properties of either nature are said of the one person."},
  hook:"\"Two whats, one who\".",
  analogy:{title:"The pen and the hand (imperfect)",text:"We say 'Shakespeare wrote Hamlet', not 'Shakespeare's hand wrote it', though the hand did the writing. Actions belong to the person through his members. Christ's human acts belong to the Son through his humanity. (The image limps: a hand is a part; Christ's humanity is a whole nature.)"},
  sort:{title:"True or false (communication of idioms)?",cats:["True","False"],items:[["God was born of Mary",0],["The divinity was born of Mary",1],["This man is God",0],["Humanity is divinity",1],["The Son of God suffered",0],["The Son suffered in his divine nature",1]]}},
 t11l5:{plain:{version:"Jesus' humanity was full of grace and, Thomas teaches, saw God directly, while also learning by experience. He took on our weakness, hunger, tiredness, sorrow and death, but not sin. His emotions were real and perfectly ordered: he wept, feared, and was angry for justice.",question:"What was Jesus' humanity like, from the inside?",one:"Full of grace, with beatific, infused and acquired knowledge, true passions perfectly ordered, and our defects freely assumed, but no sin."},
  hook:"\"Grace, Knowledge, Power, Defects\": qq.7–15 in four words.",
  analogy:{title:"The well-tuned instrument",text:"Our emotions are like an instrument that sometimes plays out of tune or starts before the conductor. Christ's were a perfectly tuned instrument, sounding every human note, grief, fear, anger, joy, exactly when and as the conductor (reason) directed."},
  sort:{title:"Did Christ assume it?",cats:["Assumed","Not assumed"],items:[["Hunger",0],["Original sin",1],["Sorrow",0],["The fomes of sin",1],["Death",0],["Ignorance (privative)",1],["Zealous anger",0]]}}
});
